/**
 * Newsletter subscription API client.
 *
 * Thin typed fetcher for the newsletter subscribe endpoint. Placed in
 * `src/lib/` (NOT `src/lib/api-client/`) because the latter is fully
 * auto-generated by openapi-ts and any hand-written file there gets wiped on
 * `yarn generate:api`. This uses the same base URL (`env.NEXT_PUBLIC_API_ENDPOINT`).
 *
 * Backend endpoint:
 *   POST /api/v1/newsletter/subscribe  (rate-limited: 10 req/min)
 */

import { env } from '@/env';

export interface SubscribePayload {
    email: string;
    consent: boolean;
    source?: string;
    locale?: string;
}

export interface SubscribeResponse {
    success: boolean;
    message: string;
    errors?: Record<string, string[]>;
}

/**
 * Subscribe an email to the newsletter.
 *
 * @returns A successful result with a user-friendly message, or a failure
 *          result with field errors. Never throws — errors are returned so the
 *          form can display them inline.
 */
export async function subscribeToNewsletter(
    payload: SubscribePayload,
): Promise<SubscribeResponse> {
    try {
        const res = await fetch(`${env.NEXT_PUBLIC_API_ENDPOINT}/api/v1/newsletter/subscribe`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                Accept: 'application/json',
                ...(payload.locale ? { 'Accept-Language': payload.locale } : {}),
            },
            body: JSON.stringify({
                email: payload.email,
                consent: payload.consent,
                source: payload.source,
            }),
        });

        const json = (await res.json()) as SubscribeResponse;

        // 422 validation errors come back with { message, errors }
        if (!res.ok) {
            return {
                success: false,
                message: json.message ?? 'Subscription failed.',
                errors: json.errors,
            };
        }

        return json;
    } catch {
        return {
            success: false,
            message: 'Network error. Please try again later.',
        };
    }
}
